from bench.evidence import EvidenceStore, VerificationChain, Verifier

class EpochOnlyChain(VerificationChain):
    """A chain that returns inclusion proofs with a per-epoch root."""
    def __init__(self):
        super().__init__()
        # create two raw records with fake hashes
        self.records = [
            {"chain_hash": "sha256:aaaa", "sealed_body": {"payload_etc": "x"}},
            {"chain_hash": "sha256:bbbb", "sealed_body": {"payload_etc": "y"}},
        ]
        self.epochs = [{"root": "sha256:epoch_root_1", "end_index": 1}]

    def verify_chain(self, verifier=None):
        return True, "ok"

    def build_inclusion_proof(self, index):
        # proof rooted at epoch, not full chain
        return {
            "chain_hash": self.records[index]["chain_hash"],
            "proof_path": [],
            "proof_root": "sha256:epoch_root_1",
        }

    def verify_inclusion_proof(self, proof, root):
        return proof.get("proof_root") == root

store = EvidenceStore(EpochOnlyChain(), "test")
bundle = store.export_bundle()          # will compute full-tree root ≠ epoch root
valid, errors = store.verify_bundle(bundle)
if not valid:
    print("FALSIFIED — bundle verification fails due to root mismatch")
else:
    # Should not happen if the bug is present
    pass

